def round_half_to_even(n):
    """
    Rounds `n` to the nearest integer, rounding ties to the nearest even number.

    :param n: The number to round.
    :return: The rounded number.
    """
    if n >= 0:
        return int(n + 0.5 - 0.5 * (n + 0.5) % 1)
    else:
        return int(n - 0.5 + 0.5 * (n - 0.5) % 1)

