def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class PointSubclass(BaseGeometry):
        type = 'Point'

        def __init__(self, coordinates=None, **kwargs):
            super().__init__(**kwargs)
            if coordinates:
                self.coordinates = coordinates

        @property
        def coordinates(self):
            return self._coordinates

        @coordinates.setter
        def coordinates(self, value):
            if isinstance(value, (list, tuple)) and len(value) == 2 and all(isinstance(x, (int, float)) for x in value):
                self._coordinates = value
            else:
                raise ValueError("Coordinates must be a list or tuple of two numeric values")

        @property
        def srid(self):
            return self._srid

        @srid.setter
        def srid(self, value):
            if value in srid_map:
                self._srid = value
            else:
                raise ValueError("Invalid SRID value")

    PointSubclass.__name__ = name
    PointSubclass.__module__ = sys._getframe().f_globals['__name__']

    for field_name, field_value in fields:
        setattr(PointSubclass, field_name, property(**field_value))

    return PointSubclass

