def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    class _TTLCache:
        def __init__(self, maxsize, ttl, timer):
            from functools import lru_cache, wraps
            self.cacheinfo = lru_cache.cache_info
            self.cache_clear = lru_cache.cache_clear
            self.cache_delete = lru_cache.cache_delete
            self.__cache = lru_cache(maxsize=maxsize, typed=typed)(self._wrapper)
            self._ttl = ttl
            self._timer = timer
            self._cache = {}

        def __call__(self, func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                return self.cache_clear()(func)(*args, **kwargs)

            return wrapper

        def _wrapper(self, func, *args, **kwargs):
            key = (func, args, frozenset(kwargs.items()))
            now = self._timer()
            if key in self._cache:
                if now - self._cache[key][1] < self._ttl:
                    return self._cache[key][0]
                del self._cache[key]
            result = func(*args, **kwargs)
            self._cache[key] = (result, now)
            return result

    return _TTLCache(maxsize, ttl, timer)

