                finally:
                    lock.release()
            else:
                key_value = key(func, args, kwargs)
                if key_value not in cache:
                    result = func(self, *args, **kwargs)
                    cache[key_value] = result
                else:
                    result = cache[key_value]
            return result
        return wrapper
    return decorator

