def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if isinstance(expr, tuple):
            a, b, op = expr
            if op == '&':
                if a == a | b:
                    result.append(a)
                elif a | (a & b) == a:
                    result.append(a)
                elif a & (~a | b) == a & b:
                    result.append(a & b)
            elif op == '|':
                if a == a | b:
                    result.append(a)
                elif a | (a & b) == a:
                    result.append(a)
                elif a | (~a & b) == a | b:
                    result.append(a | b)
        else:
            result.append(expr)
    return result

