def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """

    if version.isnumeric():
        return str(int(version) + 1)
    else:
        version_parts = version.rsplit('.', 1)
        version_base = version_parts[0]
        version_suffix = version_parts[1] if len(version_parts) == 2 else ''
        version_number = int(version_suffix.lstrip('0')) if version_suffix else 0
        return f"{version_base}.{version_number + 1}"

