    for arg in args._get_kwargs():
        if arg[0] != 'subparser_name' and arg[1] is not None:
            if args.subparser_name in parsers:
                getattr(parsers[args.subparser_name], arg[0]) = arg[1]
            else:
                parsers[args.subparser_name] = Namespace()
